<script lang="ts">
import { t, language } from '@utils/i18n'

 import {FURNITURES,OWNEDITEMS,CART,FURNITURE_PAYMENT_TYPES} from '@store/stores'
 import {ReceiveNUI} from '@utils/ReceiveNUI'
 import {SendNUI} from '@utils/SendNUI'
 let category=-1,search='',tag='all',panel='owned',selection:any=null,gizmo=false,freecam=false,busy=false,error='',confirmItem:any=null,payment='bank',preview:any=null
 const tags=(i:any)=>[i.safe?.enable?'safe':null,i.trunk?.enable?'trunk':null,i.clothing?'wardrobe':null,['sink','toilet','shower'].includes(i.hygiene?.kind)?i.hygiene.kind:null].filter(Boolean)
 const label=(v:string)=>({all:t("Todas as funções"),safe:t("Cofre"),trunk:t("Baú"),wardrobe:t("Guarda-roupa"),decor:t("Decorativo"),sink:t("Pia"),toilet:t("Vaso sanitário"),shower:t("Chuveiro")}[v]||v)
 const icon=(v:string)=>({safe:'lock',trunk:'box',wardrobe:'shirt',decor:'couch',sink:'faucet',toilet:'toilet',shower:'shower'}[v]||'couch')
 const methods=(i:any)=>i.payment?[i.payment]:$FURNITURE_PAYMENT_TYPES
 const paymentLabel=(v:string)=>({bank:t("Banco"),money:t("Dinheiro"),cash:t("Dinheiro"),crypto:t("Cripto"),coin:t("Moeda")}[v]||v)
 const paymentIcon=(v:string)=>v==='bank'?'credit-card':v==='money'||v==='cash'?'money-bill-wave':'coins'
 $: catalogue=(category<0?($FURNITURES||[]).flatMap(c=>c.items):$FURNITURES?.[category]?.items||[]).filter(i=>(t(i.label)+' '+i.label).toLowerCase().includes(search.toLowerCase())&&(tag==='all'||(tag==='decor'?tags(i).length===0:tags(i).includes(tag))))
 $: owned=$OWNEDITEMS as any[]
 $: cart=$CART as any[]
 const money=(v:number)=>'$ '+Number(v||0).toLocaleString(language,{minimumFractionDigits:2,maximumFractionDigits:2})
 ReceiveNUI('furnitureSelection',(data)=>{selection=data||null;payment=selection?.payment||selection?.selectedPayment||$FURNITURE_PAYMENT_TYPES[0]||'bank'})
 ReceiveNUI('furnitureGizmo',(data)=>{gizmo=!!data;preview=null})
 ReceiveNUI('freecamMode',(data)=>freecam=!!data)
 ReceiveNUI('updateCartItem',(data:any)=>{if(selection?.entity===data.entity){selection=data;payment=data.payment||data.selectedPayment}})
 async function send(name:string,data?:any){error='';try{return await SendNUI(name,data)}catch(_){error=t("Não foi possível concluir. Tente novamente.")}}
 async function visibility(item){busy=true;const result=await send('furnitureVisibility',{id:item.id,hidden:!item.hidden});if(!result?.success)error=result?.message||t("Falha ao guardar o móvel.");busy=false}
 async function finish(){if(!selection)return;if(selection.cart){await send('updateCartItem',{entity:selection.entity,selectedPayment:payment});await send('stopPlacement')}else if(selection.id){await send('stopPlacement')}else{const result=await send('addToCart',{...selection,selectedPayment:payment});if(result==='ok')selection=null}}
 async function remove(){if(!confirmItem)return;const result=await send('removeOwnedItem',confirmItem);if(!result?.success)error=result?.message||t("Não foi possível excluir.");confirmItem=null}
 async function stopPreview(){preview=null;await send('hoverOut')}
 async function showPreview(item){if(preview?.object===item.object){await stopPreview();return}await stopPreview();preview=item;void send('hoverIn',item)}
 async function quickAdd(item){busy=true;await stopPreview();const result=await send('quickAddFurniture',item);if(result!=='ok')error=t("Não foi possível adicionar o móvel.");else panel='cart';busy=false}
 function key(e:KeyboardEvent){if(e.target instanceof HTMLInputElement||e.target instanceof HTMLTextAreaElement||e.target instanceof HTMLSelectElement||e.repeat)return;if(e.code==='KeyC'){e.preventDefault();send('editFurnitureGizmo')}if(e.code==='KeyF'){e.preventDefault();send('freecamMode',true)}}
</script>
<svelte:window on:keydown={key}/>
{#if freecam}<div class="freecam-hint"><kbd>W A S D</kbd> {t("Navegar · Mouse: olhar ·")} <kbd>F</kbd> / <kbd>Esc</kbd> {t("Voltar ao catálogo")}</div>{/if}
<div class="furnishing" class:gizmo={gizmo||freecam}>
 {#if selection}<aside class="selection"><span class="eyebrow">{t("POSICIONAMENTO")}</span><h2>{t(selection.label)}</h2><p>{t("Use o editor 3D para mover e girar. Enter confirma; Esc cancela o ajuste.")}</p>
 <button on:click={()=>send('editFurnitureGizmo')}><i class="fa-solid fa-up-down-left-right"/> {t("Editar posição")} <kbd>C</kbd></button>
 {#if !selection.id}<label>{t("Pagamento")}<select bind:value={payment} disabled={!!selection.payment}>{#each methods(selection) as method}<option value={method}>{paymentLabel(method)}</option>{/each}</select></label>{/if}
 <button class="primary" on:click={finish}>{selection.id||selection.cart?t("Salvar alterações"):t("Adicionar ao carrinho")}</button><button on:click={()=>send('stopPlacement')}>{t("Concluir seleção")}</button></aside>{/if}
 {#if preview}<aside class="preview"><span class="eyebrow">{t("PRÉVIA 3D")}</span><strong>{t(preview.label)}</strong><button on:click={stopPreview}>{t("Fechar prévia")}</button><button class="primary" on:click={async()=>{const item=preview;await stopPreview();send('previewFurniture',item)}}>{t("Posicionar")}</button></aside>{/if}
 {#if panel}<aside class="side"><header><div><span class="eyebrow">{t("SUA RESIDÊNCIA")}</span><h2>{panel==='owned'?t("Móveis da casa"):t("Carrinho")}</h2></div><button title={t("Fechar lista")} aria-label={t("Fechar lista")} on:click={()=>panel=''}><i class="fa-solid fa-xmark"/></button></header>
 <div class="rows">
 {#if panel==='owned'}
 {#each owned as item (item.id)}<article><div class="details"><strong>{t(item.label)}</strong><small>{item.hidden?t("Guardado"):tags(item).map(label).join(' · ')||t("No ambiente")}</small></div>
 <div class="actions"><button disabled={busy||item.hidden||!item.entity} title={t("Editar posição")} aria-label={t("Editar posição")} on:click={()=>send('selectOwnedItem',item)}><i class="fa-solid fa-up-down-left-right"/></button>
 <button disabled={busy} title={item.hidden?t("Mostrar na casa"):t("Guardar móvel")} aria-label={item.hidden?t("Mostrar na casa"):t("Guardar móvel")} on:click={()=>visibility(item)}><i class={item.hidden?'fa-solid fa-eye':'fa-solid fa-box-archive'}/></button>
 <button class="danger" disabled={busy} title={t("Jogar fora")} aria-label={t("Jogar fora")} on:click={()=>confirmItem=item}><i class="fa-solid fa-trash-can"/></button></div></article>
 {:else}<p class="empty">{t("Os móveis comprados para esta casa aparecerão aqui.")}</p>{/each}
 {:else}
 {#each cart as item (item.entity)}<article><div class="details"><strong>{t(item.label)}</strong><small>{money(item.price)} · {item.hidden?t("Comprar guardado"):t("Posicionado")}</small><select aria-label={t("Pagamento de ")+item.label} value={item.payment||item.selectedPayment} disabled={!!item.payment} on:change={e=>send('updateCartItem',{entity:item.entity,selectedPayment:e.currentTarget.value})}>{#each methods(item) as method}<option value={method}>{paymentLabel(method)}</option>{/each}</select></div><div class="actions"><button title={t("Editar posição")} aria-label={t("Editar posição")} on:click={()=>send('selectCartItem',item)}><i class="fa-solid fa-up-down-left-right"/></button><button title={t("Retirar do carrinho")} aria-label={t("Retirar do carrinho")} on:click={()=>send('removeCartItem',item)}><i class="fa-solid fa-trash-can"/></button></div></article>{:else}<p class="empty">{t("Adicione produtos com + ou posicione pelo preview.")}</p>{/each}
 {/if}
 </div>{#if panel==='cart'&&cart.length}<footer><button class="primary" disabled={busy} on:click={async()=>{busy=true;await send('buyCartItems');busy=false}}>{t("Revisar e comprar ·")} {cart.length} {t("itens")}</button></footer>{/if}
 </aside>{/if}
 <section class="catalogue"><header><div><span class="eyebrow">{t("FORGE · INTERIORES")}</span><h1>{t("Monte seu espaço")}</h1></div><input aria-label={t("Buscar móveis")} placeholder={t("Buscar móvel…")} bind:value={search}/><button class:active={panel==='owned'} on:click={()=>panel=panel==='owned'?'':'owned'}><i class="fa-solid fa-couch"/> {t("Móveis da casa")} <b>{owned.length}</b></button><button class:active={panel==='cart'} on:click={()=>panel=panel==='cart'?'':'cart'}><i class="fa-solid fa-cart-shopping"/> {t("Carrinho")} <b>{cart.length}</b></button><button title={t("Fechar editor")} aria-label={t("Fechar editor")} on:click={()=>window.dispatchEvent(new KeyboardEvent('keydown',{code:'Escape'}))}><i class="fa-solid fa-xmark"/></button></header>
 <nav><button class:active={category===-1} on:click={()=>category=-1}>{t("Todos")}</button>{#each $FURNITURES||[] as item,i}<button class:active={category===i} on:click={()=>category=i}>{t(item.category)}</button>{/each}</nav>
 <div class="filters"><select aria-label={t("Filtrar por função")} bind:value={tag}>{#each ['all','decor','trunk','safe','wardrobe','sink','toilet','shower'] as value}<option {value}>{label(value)}</option>{/each}</select><button on:click={()=>send('editFurnitureGizmo')}><kbd>C</kbd> {t("Retomar edição")}</button><button on:click={()=>send('freecamMode',true)}><kbd>F</kbd> {t("Câmera livre")}</button></div>
 <div class="products">{#each catalogue as item}<article class="product"><div class="product-icon"><i class={'fa-solid fa-'+icon(tags(item)[0]||'decor')}/></div><div class="product-info"><strong>{t(item.label)}</strong><small>{item.stock==null||item.stock<0?t("Estoque ilimitado"):t('{0} disponíveis',[item.stock])}</small><div class="badges">{#each tags(item).length?tags(item):['decor'] as kind}<span>{label(kind)}</span>{/each}</div>{#each ['safe','trunk'] as kind}{#if item[kind]?.enable}<small>{label(kind)}: {item[kind].slots} {t("slots ·")} {Number(item[kind].weight||0)/1000} kg</small>{/if}{/each}<em>{money(item.price)}</em><div class="payments">{#each methods(item) as method}<i title={paymentLabel(method)} aria-label={paymentLabel(method)} class={'fa-solid fa-'+paymentIcon(method)}/>{/each}</div></div><div class="product-actions"><button title={t("Prévia 3D")} aria-label={t("Prévia 3D: ")+item.label} on:click={()=>showPreview(item)}><i class="fa-solid fa-eye"/></button><button title={t("Adicionar ao carrinho guardado")} aria-label={t("Adicionar: ")+item.label} disabled={item.stock===0||busy} on:click={()=>quickAdd(item)}><i class="fa-solid fa-plus"/></button></div></article>{:else}<p class="empty">{t("Nenhum móvel encontrado.")}</p>{/each}</div>
 {#if error}<p class="error" role="alert">{error}</p>{/if}
 </section>
 {#if confirmItem}<div class="confirm"><h2>{t("Jogar fora")} {confirmItem.label}?</h2><p>{t("O móvel será excluído da casa, sem reembolso. Use Guardar para apenas retirá-lo do ambiente.")}</p><button on:click={()=>confirmItem=null}>{t("Cancelar")}</button><button class="danger" on:click={remove}>{t("Jogar fora")}</button></div>{/if}
</div>
<style>
.furnishing{--accent:#ff7a1a;position:absolute;inset:0;font-size:13px;color:#eee;pointer-events:none}.gizmo{display:none}.furnishing section,.furnishing aside,.confirm{pointer-events:auto;background:rgba(17,17,20,.97);border:1px solid #333238;border-radius:14px;box-shadow:0 12px 40px #0006}.catalogue{position:absolute;bottom:24px;left:24px;right:24px;padding:18px 20px}.furnishing header{display:flex;align-items:center;gap:12px;margin-bottom:14px}.furnishing header>div:first-child{margin-right:auto}h1{font-size:21px;font-weight:650;margin:3px 0}h2{font-size:17px;font-weight:600;margin:4px 0}.eyebrow{font-size:10px;letter-spacing:1.7px;color:var(--accent)}button,input,select{font:inherit;border:1px solid #343339;border-radius:7px;background:#222227;color:#ddd;padding:9px 12px}button{cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:9px}button:hover{border-color:var(--accent);background:#30251e}button:disabled{opacity:.4;cursor:default}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.active{color:var(--accent);border-color:#8e4a1f;background:#2b2119}.primary{background:var(--accent);color:#1b1009;font-weight:600}.primary:hover{background:#ff943d}.danger,.danger i{color:#ff8f96}.furnishing input{width:210px}nav{display:flex;gap:7px;overflow:auto;padding:0 0 12px;white-space:nowrap}nav button{padding:6px 12px;font-size:12px}nav span{margin-left:auto;align-self:center;color:#8f8e9a;font-size:11px}kbd{font-size:11px;border:1px solid #58525a;border-radius:4px;padding:2px 5px;color:#eee}.products{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px;max-height:180px;overflow:auto}.product{text-align:left;justify-content:flex-start;padding:14px;background:#1a1a1f}.product>i:last-child{margin-left:auto;color:#6b6874}.product-icon{width:35px;height:38px;display:grid;place-items:center;background:#342417;border-radius:8px}.product-icon i{color:var(--accent)}strong{display:block;font-size:13px;font-weight:600}small{display:block;color:#94909e;font-size:11px;margin-top:5px}em{display:block;color:var(--accent);font-size:12px;font-style:normal;margin-top:7px}em span{font-size:10px;color:#888493}.side{position:absolute;right:24px;bottom:360px;width:390px;max-height:calc(100vh - 415px);display:flex;flex-direction:column;padding:16px}.rows{overflow:auto;min-height:0}.rows article{display:flex;align-items:center;gap:8px;border:1px solid #302e36;background:#1d1c22;border-radius:8px;margin-bottom:8px;padding:12px}.details{flex:1;min-width:0}.details strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.actions{display:flex;gap:5px}.actions button{width:33px;height:33px;padding:0}.empty{padding:22px 12px;font-size:12px;color:#9993a4}.selection{position:absolute;left:24px;top:60px;width:265px;padding:20px;display:flex;flex-direction:column;gap:12px}.selection p{color:#96909d;font-size:12px;line-height:1.5}.selection label{display:flex;flex-direction:column;gap:6px;font-size:12px}.selection button{width:100%}footer{padding-top:12px}footer button{width:100%}.confirm{position:absolute;left:50%;top:35%;transform:translateX(-50%);width:410px;padding:24px}.confirm p{color:#aaa3af;margin:14px 0;line-height:1.6}.confirm button{margin-right:8px}.error{color:#ff9099;margin-top:12px}.furnishing ::-webkit-scrollbar{width:5px;height:4px}.furnishing ::-webkit-scrollbar-thumb{background:#684027;border-radius:5px}@media(max-height:800px){.products{max-height:130px}.side{bottom:310px;max-height:calc(100vh - 350px)}}
.filters{display:flex;gap:8px;align-items:center;margin-bottom:10px}.filters select{margin-right:auto}.filters button{font-size:11px;padding:5px 9px}.product{display:flex;gap:10px;border:1px solid #343339;border-radius:8px}.product-info{flex:1;min-width:0}.product-actions{display:flex;flex-direction:column;gap:8px}.product-actions button{padding:8px}.badges,.payments{display:flex;gap:7px;margin-top:7px}.badges span{font-size:10px;background:#342417;color:#ffab6b;padding:2px 5px;border-radius:4px}.payments{color:#aba4b2}.rows select{padding:5px;margin-top:7px;max-width:160px}.side{bottom:410px;max-height:calc(100vh - 450px)}.preview{position:absolute;left:24px;top:24px;padding:14px;display:flex;align-items:center;gap:12px}.freecam-hint{position:absolute;bottom:30px;left:50%;transform:translateX(-50%);background:#17171cee;color:#eee;padding:14px 20px;border-radius:10px;font-size:14px}@media(max-height:800px){.side{bottom:360px;max-height:calc(100vh - 400px)}}
</style>
